API Endpoints:
- POST /dialer/sessions - Start dialer session
- GET /dialer/sessions/:id/next-lead - Get next lead for preview
- POST /dialer/sessions/:id/dial - Dial current lead
- POST /dialer/sessions/:id/skip - Skip current lead
- POST /dialer/sessions/:id/disposition - Disposition lead
- POST /dialer/sessions/:id/pause - Pause session
- POST /dialer/sessions/:id/resume - Resume session
- DELETE /dialer/sessions/:id - End session

Acceptance Criteria:
- Agent can start/pause/resume/end dialer session
- Leads presented in priority order
- Lead locking prevents concurrent access
- DNC check before dialing
- Schedule enforcement
- Proper disposition handling
- Campaign stats updated
- REAL calls made to REAL numbers

File: packages/web/src/components/agent/CallControls.tsx

```typescript
'use client';

import { useState, useCallback } from 'react';
import { useCallStore } from '@/store/call.store';
import { useWebRTC } from '@/hooks/useWebRTC';
import { Button } from '@/components/ui/button';
import { Dialpad } from './Dialpad';
import { 
  Phone, 
  PhoneOff, 
  Mic, 
  MicOff, 
  Pause, 
  Play,
  PhoneForwarded,
  Grid3X3,
  Volume2
} from 'lucide-react';

interface CallControlsProps {
  callId: string;
  onTransfer?: () => void;
  className?: string;
}

export function CallControls({ callId, onTransfer, className }: CallControlsProps) {
  const [showDialpad, setShowDialpad] = useState(false);
  const { 
    activeCall, 
    isMuted, 
    isOnHold,
    answer,
    hangup,
    hold,
    unhold,
    mute,
    unmute,
    sendDtmf
  } = useCallStore();

  const { localStream } = useWebRTC();

  const handleAnswer = useCallback(async () => {
    if (!activeCall) return;
    try {
      await answer(callId);
    } catch (error) {
      console.error('Failed to answer call:', error);
    }
  }, [callId, answer, activeCall]);

  const handleHangup = useCallback(async () => {
    try {
      await hangup(callId);
    } catch (error) {
      console.error('Failed to hangup:', error);
    }
  }, [callId, hangup]);

  const handleHold = useCallback(async () => {
    try {
      if (isOnHold) {
        await unhold(callId);
      } else {
        await hold(callId);
      }
    } catch (error) {
      console.error('Failed to toggle hold:', error);
    }
  }, [callId, isOnHold, hold, unhold]);

  const handleMute = useCallback(async () => {
    try {
      if (isMuted) {
        await unmute(callId);
      } else {
        await mute(callId);
      }
    } catch (error) {
      console.error('Failed to toggle mute:', error);
    }
  }, [callId, isMuted, mute, unmute]);

  const handleDtmf = useCallback((digit: string) => {
    sendDtmf(callId, digit);
    // Play local DTMF tone feedback
    const audio = new Audio(`/sounds/dtmf-${digit}.wav`);
    audio.play().catch(() => {});
  }, [callId, sendDtmf]);

  if (!activeCall) {
    return null;
  }

  const isRinging = activeCall.status === 'ringing';
  const isActive = activeCall.status === 'answered';

  return (
    <div className={`flex items-center gap-2 p-4 bg-background border rounded-lg ${className}`}>
      {/* Answer/Hangup */}
      {isRinging && activeCall.direction === 'inbound' && (
        <Button
          variant="default"
          size="lg"
          className="bg-green-600 hover:bg-green-700"
          onClick={handleAnswer}
          aria-label="Answer call"
        >
          <Phone className="w-5 h-5 mr-2" />
          Answer
        </Button>
      )}

      <Button
        variant="destructive"
        size="lg"
        onClick={handleHangup}
        aria-label="Hangup call"
      >
        <PhoneOff className="w-5 h-5 mr-2" />
        Hangup
      </Button>

      {/* Active call controls */}
      {isActive && (
        <>
          {/* Mute */}
          <Button
            variant={isMuted ? 'secondary' : 'outline'}
            size="icon"
            onClick={handleMute}
            aria-label={isMuted ? 'Unmute' : 'Mute'}
            aria-pressed={isMuted}
          >
            {isMuted ? <MicOff className="w-5 h-5" /> : <Mic className="w-5 h-5" />}
          </Button>

          {/* Hold */}
          <Button
            variant={isOnHold ? 'secondary' : 'outline'}
            size="icon"
            onClick={handleHold}
            aria-label={isOnHold ? 'Resume' : 'Hold'}
            aria-pressed={isOnHold}
          >
            {isOnHold ? <Play className="w-5 h-5" /> : <Pause className="w-5 h-5" />}
          </Button>

          {/* Dialpad Toggle */}
          <Button
            variant={showDialpad ? 'secondary' : 'outline'}
            size="icon"
            onClick={() => setShowDialpad(!showDialpad)}
            aria-label="Toggle dialpad"
            aria-expanded={showDialpad}
          >
            <Grid3X3 className="w-5 h-5" />
          </Button>

          {/* Transfer */}
          {onTransfer && (
            <Button
              variant="outline"
              size="icon"
              onClick={onTransfer}
              aria-label="Transfer call"
            >
              <PhoneForwarded className="w-5 h-5" />
            </Button>
          )}
        </>
      )}

      {/* Dialpad Popover */}
      {showDialpad && isActive && (
        <div className="absolute bottom-full mb-2 left-0">
          <Dialpad onDigit={handleDtmf} />
        </div>
      )}
    </div>
  );
}
