  "dependencies": {
    "sip.js": "^0.21.2"
  }
}
```

Configuration:
- SIP_SERVER: WebSocket SIP server URL
- SIP_USER: Extension/username
- SIP_PASSWORD: SIP password
- ICE_SERVERS: STUN/TURN servers

Usage:
```typescript
const webrtc = useWebRTC({
  sipServer: 'sip.example.com',
  sipUser: 'agent001',
  sipPassword: '***',
  iceServers: [{ urls: 'stun:stun.l.google.com:19302' }],
});

// Register
await webrtc.register();

// Make call
await webrtc.makeCall('1234567890');

// Answer incoming
await webrtc.answerCall();
```

Acceptance Criteria:
- SIP registration working
- Outbound calls working
- Inbound calls detected and answerable
- Audio streams properly managed
- Mute toggle working
- Cleanup on hangup/unmount
- Works with REAL SIP server

File: packages/web/src/components/admin/ivr-builder/IvrCanvas.tsx

```typescript
'use client';

import { useCallback, useState, useMemo } from 'react';
import ReactFlow, {
  Node,
  Edge,
  Connection,
  addEdge,
  Background,
  Controls,
  MiniMap,
  useNodesState,
  useEdgesState,
  NodeTypes,
  EdgeTypes,
  MarkerType,
  Panel,
} from 'reactflow';
import 'reactflow/dist/style.css';

import { MenuNode } from './nodes/MenuNode';
import { AnnouncementNode } from './nodes/AnnouncementNode';
import { QueueNode } from './nodes/QueueNode';
import { TimeCheckNode } from './nodes/TimeCheckNode';
import { TransferNode } from './nodes/TransferNode';
import { HangupNode } from './nodes/HangupNode';
import { StartNode } from './nodes/StartNode';
import { CustomEdge } from './edges/CustomEdge';
import { NodePalette } from './NodePalette';
import { IvrToolbar } from './IvrToolbar';
import { IvrPropertiesPanel } from './IvrPropertiesPanel';
import { useIvrStore } from '@/store/ivr.store';

const nodeTypes: NodeTypes = {
  start: StartNode,
  menu: MenuNode,
  announcement: AnnouncementNode,
  queue: QueueNode,
  timeCheck: TimeCheckNode,
  transfer: TransferNode,
  hangup: HangupNode,
};

const edgeTypes: EdgeTypes = {
  custom: CustomEdge,
};

interface IvrCanvasProps {
  ivrId?: string;
  readOnly?: boolean;
  onSave?: (flow: IvrFlow) => Promise<void>;
}

export interface IvrFlow {
  id: string;
  name: string;
  nodes: Node[];
  edges: Edge[];
  settings: Record<string, any>;
}

export function IvrCanvas({ ivrId, readOnly, onSave }: IvrCanvasProps) {
  const [nodes, setNodes, onNodesChange] = useNodesState([]);
  const [edges, setEdges, onEdgesChange] = useEdgesState([]);
  const [selectedNode, setSelectedNode] = useState<Node | null>(null);
  const { saveFlow, publishFlow, testFlow } = useIvrStore();

  const onConnect = useCallback(
    (params: Connection) => {
      setEdges((eds) =>
        addEdge(
          {
            ...params,
            type: 'custom',
            markerEnd: { type: MarkerType.ArrowClosed },
            data: { label: '' },
          },
          eds
        )
      );
    },
    [setEdges]
  );

  const onNodeClick = useCallback((event: React.MouseEvent, node: Node) => {
    setSelectedNode(node);
  }, []);

  const onPaneClick = useCallback(() => {
    setSelectedNode(null);
  }, []);

  const onDrop = useCallback(
    (event: React.DragEvent) => {
      event.preventDefault();

      const type = event.dataTransfer.getData('application/reactflow');
      if (!type) return;

      const position = {
        x: event.clientX - 250,
        y: event.clientY - 100,
      };

      const newNode: Node = {
        id: `${type}-${Date.now()}`,
        type,
        position,
        data: getDefaultNodeData(type),
      };

      setNodes((nds) => [...nds, newNode]);
    },
    [setNodes]
  );

  const onDragOver = useCallback((event: React.DragEvent) => {
    event.preventDefault();
    event.dataTransfer.dropEffect = 'move';
  }, []);

  const updateNodeData = useCallback(
    (nodeId: string, data: any) => {
      setNodes((nds) =>
        nds.map((node) =>
          node.id === nodeId ? { ...node, data: { ...node.data, ...data } } : node
        )
      );
    },
    [setNodes]
  );

  const handleSave = async () => {
    const flow: IvrFlow = {
      id: ivrId || '',
      name: 'Untitled IVR',
      nodes,
      edges,
      settings: {},
    };
    await saveFlow(flow);
    onSave?.(flow);
  };

  const handlePublish = async () => {
    await publishFlow(ivrId!);
  };

  const handleTest = async () => {
    await testFlow(ivrId!, '+15551234567');
  };

  return (
    <div className="flex h-full">
      {/* Left Palette */}
      <NodePalette disabled={readOnly} />

      {/* Canvas */}
      <div className="flex-1 h-full">
        <ReactFlow
          nodes={nodes}
          edges={edges}
          onNodesChange={onNodesChange}
          onEdgesChange={onEdgesChange}
          onConnect={onConnect}
          onNodeClick={onNodeClick}
          onPaneClick={onPaneClick}
          onDrop={onDrop}
          onDragOver={onDragOver}
          nodeTypes={nodeTypes}
          edgeTypes={edgeTypes}
          fitView
          snapToGrid
          snapGrid={[15, 15]}
          nodesDraggable={!readOnly}
          nodesConnectable={!readOnly}
          elementsSelectable={!readOnly}
        >
          <Background gap={15} />
          <Controls />
          <MiniMap />

          <Panel position="top-right">
            <IvrToolbar
              onSave={handleSave}
              onPublish={handlePublish}
              onTest={handleTest}
              readOnly={readOnly}
            />
          </Panel>
        </ReactFlow>
      </div>

      {/* Right Properties Panel */}
      {selectedNode && (
        <IvrPropertiesPanel
          node={selectedNode}
          onUpdate={(data) => updateNodeData(selectedNode.id, data)}
          onClose={() => setSelectedNode(null)}
        />
      )}
    </div>
  );
}

function getDefaultNodeData(type: string): any {
  const defaults: Record<string, any> = {
    start: { label: 'Start', extension: '' },
    menu: { 
      label: 'Menu', 
      prompt: '', 
      options: [
        { digit: '1', label: 'Option 1', next: '' },
        { digit: '2', label: 'Option 2', next: '' },
      ],
      timeout: 5,
      maxRetries: 3,
    },
    announcement: { 
      label: 'Announcement', 
      audioFile: '', 
      text: '',
      useTTS: false,
    },
    queue: { 
      label: 'Queue', 
      queueId: '', 
      announcePosition: true,
      announceHoldTime: true,
    },
    timeCheck: { 
      label: 'Time Check',
      schedule: {
        monday: { start: '09:00', end: '18:00' },
        tuesday: { start: '09:00', end: '18:00' },
        wednesday: { start: '09:00', end: '18:00' },
        thursday: { start: '09:00', end: '18:00' },
        friday: { start: '09:00', end: '18:00' },
      },
      holidays: [],
    },
    transfer: { 
      label: 'Transfer', 
      destination: '', 
      type: 'extension',
    },
    hangup: { label: 'Hangup', playGoodbye: true },
  };

  return defaults[type] || { label: type };
}
```

