```typescript
import { Injectable, Logger } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository, DataSource } from 'typeorm';
import { AuditLog, AuditAction, AuditResource } from './entities/audit-log.entity';
import { CreateAuditLogDto } from './dto/create-audit-log.dto';

@Injectable()
export class AuditService {
  private readonly logger = new Logger(AuditService.name);

  constructor(
    @InjectRepository(AuditLog)
    private readonly auditRepo: Repository<AuditLog>,
    private readonly dataSource: DataSource,
  ) {}

  async log(dto: CreateAuditLogDto): Promise<AuditLog> {
    const auditLog = this.auditRepo.create({
      ...dto,
      timestamp: new Date(),
      ipAddress: dto.ipAddress,
      userAgent: dto.userAgent,
    });

    // Use raw query to bypass RLS (audit logs should always be written)
    const result = await this.dataSource.query(
      `INSERT INTO audit_logs 
        (tenant_id, user_id, action, resource, resource_id, details, ip_address, user_agent, timestamp)
       VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
       RETURNING *`,
      [
        dto.tenantId,
        dto.userId,
        dto.action,
        dto.resource,
        dto.resourceId,
        JSON.stringify(dto.details || {}),
        dto.ipAddress,
        dto.userAgent,
        new Date(),
      ],
    );

    return result[0];
  }

  // Convenience methods for common audit events

  async logLogin(
    tenantId: string,
    userId: string,
    success: boolean,
    ipAddress: string,
    userAgent: string,
    details?: Record<string, any>,
  ): Promise<void> {
    await this.log({
      tenantId,
      userId,
      action: success ? AuditAction.LOGIN : AuditAction.LOGIN_FAILED,
      resource: AuditResource.AUTH,
      details: {
        success,
        ...details,
      },
      ipAddress,
      userAgent,
    });
  }

  async logLogout(
    tenantId: string,
    userId: string,
    ipAddress: string,
    userAgent: string,
  ): Promise<void> {
    await this.log({
      tenantId,
      userId,
      action: AuditAction.LOGOUT,
      resource: AuditResource.AUTH,
      ipAddress,
      userAgent,
    });
  }

  async logCreate(
    tenantId: string,
    userId: string,
    resource: AuditResource,
    resourceId: string,
    details: Record<string, any>,
    ipAddress: string,
    userAgent: string,
  ): Promise<void> {
    await this.log({
      tenantId,
      userId,
      action: AuditAction.CREATE,
      resource,
      resourceId,
      details,
      ipAddress,
      userAgent,
    });
  }

  async logUpdate(
    tenantId: string,
    userId: string,
    resource: AuditResource,
    resourceId: string,
    before: Record<string, any>,
    after: Record<string, any>,
    ipAddress: string,
    userAgent: string,
  ): Promise<void> {
    await this.log({
      tenantId,
      userId,
      action: AuditAction.UPDATE,
      resource,
      resourceId,
      details: {
        before,
        after,
        changes: this.computeChanges(before, after),
      },
      ipAddress,
      userAgent,
    });
  }

  async logDelete(
    tenantId: string,
    userId: string,
    resource: AuditResource,
    resourceId: string,
    deletedData: Record<string, any>,
    ipAddress: string,
    userAgent: string,
  ): Promise<void> {
    await this.log({
      tenantId,
      userId,
      action: AuditAction.DELETE,
      resource,
      resourceId,
      details: { deletedData },
      ipAddress,
      userAgent,
    });
  }

  async logRecordingAccess(
    tenantId: string,
    userId: string,
    recordingId: string,
    action: 'playback' | 'download',
    ipAddress: string,
    userAgent: string,
  ): Promise<void> {
    await this.log({
      tenantId,
      userId,
      action: AuditAction.ACCESS,
      resource: AuditResource.RECORDING,
      resourceId: recordingId,
      details: { accessType: action },
      ipAddress,
      userAgent,
    });
  }

  async logConfigChange(
    tenantId: string,
    userId: string,
    configKey: string,
    before: any,
    after: any,
    ipAddress: string,
    userAgent: string,
  ): Promise<void> {
    await this.log({
      tenantId,
      userId,
      action: AuditAction.CONFIG_CHANGE,
      resource: AuditResource.SETTINGS,
      details: {
        key: configKey,
        before,
        after,
      },
      ipAddress,
      userAgent,
    });
  }

  // Query methods

  async findAll(
    tenantId: string,
    filters: {
      userId?: string;
      action?: AuditAction;
      resource?: AuditResource;
      startDate?: Date;
      endDate?: Date;
      page?: number;
      limit?: number;
    },
  ): Promise<{ data: AuditLog[]; total: number }> {
    const query = this.auditRepo
      .createQueryBuilder('log')
      .where('log.tenantId = :tenantId', { tenantId })
      .orderBy('log.timestamp', 'DESC');

    if (filters.userId) {
      query.andWhere('log.userId = :userId', { userId: filters.userId });
    }

    if (filters.action) {
      query.andWhere('log.action = :action', { action: filters.action });
    }

    if (filters.resource) {
      query.andWhere('log.resource = :resource', { resource: filters.resource });
    }

    if (filters.startDate) {
      query.andWhere('log.timestamp >= :startDate', { startDate: filters.startDate });
    }

    if (filters.endDate) {
      query.andWhere('log.timestamp <= :endDate', { endDate: filters.endDate });
    }

    const page = filters.page || 1;
    const limit = filters.limit || 50;
    const offset = (page - 1) * limit;

    const [data, total] = await query
      .skip(offset)
      .take(limit)
      .getManyAndCount();

    return { data, total };
  }

  private computeChanges(
    before: Record<string, any>,
    after: Record<string, any>,
  ): Record<string, { from: any; to: any }> {
    const changes: Record<string, { from: any; to: any }> = {};

    const allKeys = new Set([
      ...Object.keys(before || {}),
      ...Object.keys(after || {}),
    ]);

    for (const key of allKeys) {
      if (JSON.stringify(before?.[key]) !== JSON.stringify(after?.[key])) {
        changes[key] = {
          from: before?.[key],
          to: after?.[key],
        };
      }
    }

    return changes;
  }
}
