'use client';

import { useEffect, useState } from 'react';
import {
  Phone,
  PhoneOff,
  Pause,
  Play,
  Mic,
  MicOff,
  PhoneForwarded,
  Users,
  Circle,
  Square,
  Volume2,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Slider } from '@/components/ui/slider';
import { TransferDialog } from './TransferDialog';
import { ConferenceDialog } from './ConferenceDialog';
import { DispositionDialog } from './DispositionDialog';
import { useAgentStore, Call } from '@/store/agent.store';
import { formatDuration, cn } from '@/lib/utils';

interface CallPanelProps {
  call: Call;
  className?: string;
}

export function CallPanel({ call, className }: CallPanelProps) {
  const {
    answerCall,
    hangupCall,
    holdCall,
    resumeCall,
    muteCall,
    unmuteCall,
    startRecording,
    stopRecording,
  } = useAgentStore();

  const [transferOpen, setTransferOpen] = useState(false);
  const [conferenceOpen, setConferenceOpen] = useState(false);
  const [volume, setVolume] = useState(80);
  const [showDisposition, setShowDisposition] = useState(false);

  const isRinging = call.state === 'ringing';
  const isConnected = call.state === 'connected';
  const isOnHold = call.state === 'on-hold';

  const handleHangup = async () => {
    await hangupCall();
    setShowDisposition(true);
  };

  const handleVolumeChange = (value: number[]) => {
    setVolume(value[0]);
    // Apply volume to audio element
    const audio = document.querySelector('audio');
    if (audio) {
      audio.volume = value[0] / 100;
    }
  };

  return (
    <>
      <div className={cn("bg-card p-4", className)}>
        <div className="flex items-center justify-between">
          {/* Left: Caller Info */}
          <div className="flex items-center gap-4">
            {/* Call Direction Indicator */}
            <div className={cn(
              "w-12 h-12 rounded-full flex items-center justify-center",
              call.direction === 'inbound' ? "bg-blue-500" : "bg-green-500"
            )}>
              <Phone className="w-6 h-6 text-white" />
            </div>

            {/* Caller Details */}
            <div>
              <div className="text-lg font-semibold">
                {call.callerName || 'Unknown Caller'}
              </div>
              <div className="text-sm text-muted-foreground">
                {call.callerNumber}
              </div>
              {call.queueName && (
                <Badge variant="secondary" className="mt-1">
                  {call.queueName}
                </Badge>
              )}
            </div>

            {/* Call State */}
            <Badge 
              variant={isRinging ? 'destructive' : isOnHold ? 'secondary' : 'default'}
              className="animate-pulse"
            >
              {isRinging && 'Ringing'}
              {isConnected && 'Connected'}
              {isOnHold && 'On Hold'}
            </Badge>

            {/* Duration */}
            {!isRinging && (
              <div className="text-lg font-mono">
                {formatDuration(call.duration)}
              </div>
            )}

            {/* Recording Indicator */}
            {call.isRecording && (
              <div className="flex items-center gap-1 text-red-500">
                <Circle className="w-3 h-3 fill-current animate-pulse" />
                <span className="text-sm">REC</span>
              </div>
            )}
          </div>

          {/* Right: Call Controls */}
          <div className="flex items-center gap-2">
            {/* Ringing Controls */}
            {isRinging && (
              <>
                <Button
                  size="lg"
                  className="bg-green-500 hover:bg-green-600 gap-2"
                  onClick={answerCall}
                >
                  <Phone className="w-5 h-5" />
                  Answer
                </Button>
                <Button
                  size="lg"
                  variant="destructive"
                  className="gap-2"
                  onClick={handleHangup}
                >
                  <PhoneOff className="w-5 h-5" />
                  Reject
                </Button>
              </>
            )}

            {/* Connected Controls */}
            {(isConnected || isOnHold) && (
              <>
                {/* Mute */}
                <Button
                  variant={call.isMuted ? 'destructive' : 'outline'}
                  size="icon"
                  onClick={call.isMuted ? unmuteCall : muteCall}
                  title={call.isMuted ? 'Unmute' : 'Mute'}
                >
                  {call.isMuted ? (
                    <MicOff className="w-5 h-5" />
                  ) : (
                    <Mic className="w-5 h-5" />
                  )}
                </Button>

                {/* Hold/Resume */}
                <Button
                  variant={isOnHold ? 'default' : 'outline'}
                  size="icon"
                  onClick={isOnHold ? resumeCall : holdCall}
                  title={isOnHold ? 'Resume' : 'Hold'}
                >
                  {isOnHold ? (
                    <Play className="w-5 h-5" />
                  ) : (
                    <Pause className="w-5 h-5" />
                  )}
                </Button>

                {/* Recording */}
                <Button
                  variant={call.isRecording ? 'destructive' : 'outline'}
                  size="icon"
                  onClick={call.isRecording ? stopRecording : startRecording}
                  title={call.isRecording ? 'Stop Recording' : 'Start Recording'}
                >
                  {call.isRecording ? (
                    <Square className="w-5 h-5" />
                  ) : (
                    <Circle className="w-5 h-5" />
                  )}
                </Button>

                {/* Transfer */}
                <Button
                  variant="outline"
                  size="icon"
                  onClick={() => setTransferOpen(true)}
                  title="Transfer"
                >
                  <PhoneForwarded className="w-5 h-5" />
                </Button>

                {/* Conference */}
                <Button
                  variant="outline"
                  size="icon"
                  onClick={() => setConferenceOpen(true)}
                  title="Add to Conference"
                >
                  <Users className="w-5 h-5" />
                </Button>

                {/* Volume */}
                <div className="flex items-center gap-2 w-32">
                  <Volume2 className="w-4 h-4 text-muted-foreground" />
                  <Slider
                    value={[volume]}
                    onValueChange={handleVolumeChange}
                    max={100}
                    step={1}
                  />
                </div>

                {/* Hangup */}
                <Button
                  variant="destructive"
                  size="lg"
                  className="gap-2"
                  onClick={handleHangup}
                >
                  <PhoneOff className="w-5 h-5" />
                  End Call
                </Button>
              </>
            )}
          </div>
        </div>
      </div>

      {/* Transfer Dialog */}
      <TransferDialog
        open={transferOpen}
        onOpenChange={setTransferOpen}
        callId={call.id}
      />

      {/* Conference Dialog */}
      <ConferenceDialog
        open={conferenceOpen}
        onOpenChange={setConferenceOpen}
        callId={call.id}
      />

      {/* Disposition Dialog */}
      <DispositionDialog
        open={showDisposition}
        onOpenChange={setShowDisposition}
        callId={call.id}
      />
    </>
  );
}
